#include <iostream>
using namespace std;

const long long M = 998244353;

long long power(long long base, long long exponent) {
    long long result = 1;
    long long m = M;
    while (exponent > 0) {
        if (exponent & 1) {
            result = (result * base) % m;
        }
        base = (base * base) % m;
        exponent >>= 1;
    }
    return result;
}

long long modInverse(long long a, long long m) {
    return power(a, m - 2);
}

int main() {
    long long m, n, l, r;
    cin >> m >> n >> l >> r;

    long long T = m * n;
    long long num = r - l + 1;

    long long a = power(num, T);
    if (T % 2 == 1) {
        cout << a << "\n";
    } else {
        if (num % 2 == 0)
            cout << (a * modInverse(2, M)) % M << "\n";
        else
            cout << (((a + 1) % M) * modInverse(2, M)) % M << "\n";
    }
    return 0;
}

